/**
 * Row shapes for the Muse read views.
 *
 * Hand-written on purpose: `src/integrations/supabase/types.ts` is generated by
 * Lovable and would drop these on its next regeneration. Keep this file in sync
 * with supabase/migrations/20260925120000_muse_executive_layer.sql and
 * supabase/migrations/20260927120000_muse_mission_board.sql.
 */

export type MuseDataStatus =
  | "KNOWN"
  | "AVAILABLE_NOT_CONNECTED"
  | "SOURCE_EXISTS_ACCESS_NEEDED"
  | "NOT_MEASURED"
  | "UNKNOWN"
  | "NEEDS_VERIFICATION";

export type MuseClassification =
  | "FENDI_DECISION"
  | "MUSE_ANALYSIS"
  | "DELEGATE_TO_AGENT"
  | "AUTOMATED_SYSTEM"
  | "HUMAN_OWNER"
  | "WAITING";

export type MuseVerificationState =
  | "CLAIMED"
  | "ARTIFACT_VERIFIED"
  | "SYSTEM_VERIFIED"
  | "LIVE_VERIFIED";

export type MuseSystemStatus =
  | "HEALTHY"
  | "FAILING"
  | "STALE"
  | "NEVER_RAN"
  | "NOT_OBSERVED"
  | "DISABLED"
  | "UNKNOWN";

export type MuseBriefSection =
  | "priorities"
  | "decisions_required"
  | "blockers"
  | "waiting"
  | "financial"
  | "system_failures"
  | "opportunities"
  | "commitments";

export interface MuseBriefRow {
  section: MuseBriefSection;
  rank: number;
  item_type: "open_loop" | "decision" | "system" | "task" | "improvement";
  item_id: string;
  title: string;
  domain_key: string;
  domain_name: string;
  detail: string | null;
  classification: MuseClassification;
  owner: string | null;
  due_at: string | null;
  source: string | null;
  source_ref: string | null;
  data_status: MuseDataStatus;
  verification_state: MuseVerificationState;
  as_of: string;
}

