export type MuseAttentionFlag = "ATTENDED" | "UNDER_ATTENDED" | "QUIET" | "INSUFFICIENT_HISTORY";

export type MuseImprovementStatus =
  | "PROPOSED"
  | "SELECTED"
  | "IN_EXECUTION"
  | "VERIFICATION"
  | "MEASURING"
  | "DECIDED"
  | "CLOSED"
  | "REJECTED";

export type MuseVerdict = "PENDING" | "KEEP" | "REVISE" | "REVERSE" | "INCONCLUSIVE";

export type MuseTaskState =
  | "ASSIGNED"
  | "IN_PROGRESS"
  | "WAITING"
  | "BLOCKED"
  | "IMPLEMENTED"
  | "VERIFICATION"
  | "COMPLETE"
  | "CANCELLED";

export type MuseOwnerAttention = "NONE" | "INFORM" | "APPROVAL" | "DECISION" | "DIRECT_INVOLVEMENT";

export type MuseLevel = "HIGH" | "MEDIUM" | "LOW";

